    h, m = map(int, t.split(':'))
    return h * 60 + m

def to_str(m):
    h = m // 60
    mins = m % 60
    return f"{h:02d}:{mins:02d}"

def complement(busy, work_start, work_end):
    """Return free intervals within work hours given busy intervals (list of (start,end) in minutes)."""
    free = []
    cur = work_start
    for s, e in sorted(busy):
        if cur < s:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def intersect_intervals(lists):
    """Intersect multiple lists of intervals."""
    if not lists:
        return []
    # start with first list
    result = lists[0][:]
    for other in lists[1:]:
        new_res = []
        i = j = 0
        while i < len(result) and j < len(other):
            a_start, a_end = result[i]
            b_start, b_end = other[j]
            start = max(a_start, b_start)
            end = min(a_end, b_end)
            if start < end:
                new_res.append((start, end))
            if a_end <= b_end:
                i += 1
            else:
                j += 1
        result = new_res
        if not result:
            break
    return result

