from itertools import permutations, product


def format_time(total_minutes):
    hour, minute = divmod(total_minutes, 60)
    period = "AM" if hour < 12 else "PM"
    hour12 = hour % 12
    if hour12 == 0:
        hour12 = 12
    return f"{hour12}:{minute:02d}{period}"


start_location = "North Beach"
start_time = 9 * 60

locations = {"North Beach", "Union Square", "Russian Hill"}
travel_minutes = {
    ("North Beach", "Union Square"): 7,
    ("North Beach", "Russian Hill"): 4,
    ("Union Square", "North Beach"): 10,
    ("Union Square", "Russian Hill"): 13,
    ("Russian Hill", "North Beach"): 5,
    ("Russian Hill", "Union Square"): 11,
}
for location in locations:
    travel_minutes[(location, location)] = 0

friends = [
    ("Emily", "Union Square", 16 * 60, 17 * 60 + 15, 45),
    ("Margaret", "Russian Hill", 19 * 60, 21 * 60, 120),
]

best_statements = None
best_score = None

for count in range(1, len(friends) + 1):
    for chosen in permutations(friends, count):
        start_ranges = []
        possible = True

        for friend in chosen:
            _, _, available_start, available_end, min_duration = friend
            latest_start = available_end - min_duration
            if latest_start < available_start:
                possible = False
                break
            start_ranges.append(range(available_start, latest_start + 1))

        if not possible:
            continue

        for meeting_starts in product(*start_ranges):
            current_time = start_time
            current_location = start_location
            statements = [
                f"You start at {start_location} at {format_time(start_time)}."
            ]
            total_wait = 0
            feasible = True

            for friend, meeting_start in zip(chosen, meeting_starts):
                name, location, available_start, available_end, min_duration = friend
                travel = travel_minutes[(current_location, location)]
                arrival_time = current_time + travel

                if arrival_time > meeting_start:
                    feasible = False
                    break

                if travel != 0:
                    statements.append(
                        f"You travel to {location} in {travel} minutes and arrive at {format_time(arrival_time)}."
                    )

                if arrival_time < meeting_start:
                    total_wait += meeting_start - arrival_time
                    statements.append(
                        f"You wait until {format_time(meeting_start)}."
                    )

                meeting_end = meeting_start + min_duration
                statements.append(
                    f"You meet {name} for {min_duration} minutes from {format_time(meeting_start)} to {format_time(meeting_end)}."
                )

                current_time = meeting_end
                current_location = location

            if not feasible:
                continue

            score = (-count, total_wait, current_time, meeting_starts)
            if best_score is None or score < best_score:
                best_score = score
                best_statements = statements

